type DataType = 'boolean' | 'integer' | 'float' | 'string' | 'json' | string;

interface SettingItem {
  key: string;
  value: any;
  description?: string;
  category?: string;
  data_type?: DataType;
  is_configurable?: boolean;
  created_at?: string;
  updated_at?: string;
}

interface SettingsResponse {
  items: SettingItem[];
  total: number;
}

