function inferDataType(item: SettingItem): DataType {
  if (item.data_type) return item.data_type;
  const k = item.key;
  if (k.endsWith('.enabled') || typeof item.value === 'boolean') return 'boolean';
  if (/(minutes|seconds|max|limit|batch_size|tokens)/i.test(k)) return 'integer';
  if (/temperature/i.test(k)) return 'float';
  if (/json|schema|config/.test(k) || typeof item.value === 'object') return 'json';
  return 'string';
}

const editorFor = (
  item: SettingItem,
  draft: any,
  setDraft: (v: any) => void
) => {
  const type = inferDataType(item);
  // Спец‑селекты для провайдеров LLM
  const providerKeys = new Set(['llm_provider_default', 'llm_provider_service_default']);
  if (providerKeys.has(item.key)) {
    return (
      <select value={String(draft ?? '')} onChange={(e) => setDraft(e.target.value)} style={{ minWidth: 180 }}>
        <option value="deepseek">deepseek</option>
        <option value="gigachat">gigachat</option>
        <option value="openai">openai</option>
      </select>
    );
  }
  if (type === 'boolean') {
    return <Switch checked={Boolean(draft)} onChange={(v) => setDraft(v)} />;
  }
  if (type === 'integer') {
    return <InputNumber style={{ width: 140 }} value={Number(draft ?? 0)} onChange={(v) => setDraft(typeof v === 'number' ? Math.trunc(v) : 0)} />;
  }
  if (type === 'float') {
    return <InputNumber style={{ width: 140 }} step={0.1} value={Number(draft ?? 0)} onChange={(v) => setDraft(typeof v === 'number' ? v : 0)} />;
  }
  if (type === 'json') {
    return (
      <Input.TextArea
        value={typeof draft === 'string' ? draft : JSON.stringify(draft ?? {}, null, 2)}
        onChange={(e) => setDraft(e.target.value)}
        autoSize={{ minRows: 2, maxRows: 6 }}
      />
    );
  }
  return <Input style={{ minWidth: 180 }} value={String(draft ?? '')} onChange={(e) => setDraft(e.target.value)} />;
};

const normalizeOutgoingValue = (item: SettingItem, draft: any): string => {
  const type = inferDataType(item);
  if (type === 'json') {
    // Валидация JSON
    try {
      const parsed = typeof draft === 'string' ? JSON.parse(draft) : draft;
      return JSON.stringify(parsed);
    } catch (e) {
      throw new Error('Неверный JSON');
    }
  }
  if (type === 'boolean') return String(Boolean(draft));
  if (type === 'integer') return String(parseInt(String(draft || '0'), 10));
  if (type === 'float') return String(parseFloat(String(draft || '0')));
  return String(draft ?? '');
};

// Компонент таблицы категории (перенос из функции с хуками)
const CategoryTable: React.FC<{
  list: SettingItem[];
  savingKey: string | null;
  onSave: (item: SettingItem, draft: any) => void | Promise<void>;
}> = ({ list, savingKey, onSave }) => {
  const [drafts, setDrafts] = useState<Record<string, any>>({});
  const setDraft = (key: string, v: any) => setDrafts(prev => ({ ...prev, [key]: v }));

  const columns = [
    { title: 'Ключ', dataIndex: 'key', key: 'key', width: 280, render: (v: string) => <Text code>{v}</Text> },
    { title: 'Описание', dataIndex: 'description', key: 'description', width: 360, render: (v: string) => <Text type="secondary">{v || '-'}</Text> },
    {
      title: 'Значение', key: 'value', width: 360,
      render: (rec: SettingItem) => editorFor(
        rec,
        drafts[rec.key] !== undefined ? drafts[rec.key] : rec.value,
        (v) => setDraft(rec.key, v)
      )
    },
    {
      title: 'Действие', key: 'action', width: 140,
      render: (rec: SettingItem) => (
        <Button
          type="primary"
          icon={<SaveOutlined />}
          loading={savingKey === rec.key}
          onClick={() => onSave(rec, drafts[rec.key] !== undefined ? drafts[rec.key] : rec.value)}
        >
          Save
        </Button>
      )
    }
  ];

  return (
    <Table
      rowKey="key"
      dataSource={list}
      columns={columns as any}
      pagination={{ pageSize: 10, showSizeChanger: true, pageSizeOptions: [10, 20, 50] }}
      size="small"
      scroll={{ x: true }}
    />
  );
};

const SystemSettings: React.FC = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [items, setItems] = useState<SettingItem[]>([]);
  const [activeTab, setActiveTab] = useState<string>('LLM');
  const [savingKey, setSavingKey] = useState<string | null>(null);
  const [llmTestLoading, setLlmTestLoading] = useState(false);
  const [llmTestResult, setLlmTestResult] = useState<{ ok: boolean; provider?: string; detail?: string } | null>(null);

  const loadAll = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await apiRequest('/api/admin/soul/settings/all', 'GET');
      const list = (data as SettingsResponse)?.items || [];
      setItems(list);
    } catch (e: any) {
      setError(e?.message || 'Ошибка загрузки настроек');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAll();
  }, []);

  const groups = useMemo(() => {
    const byTab: Record<string, SettingItem[]> = {};
    CATEGORY_TABS.forEach(t => (byTab[t.key] = []));
    // Разложим существующие
    items.forEach((it) => {
      const tab = CATEGORY_TABS.find(t => t.matcher(it));
      if (tab) byTab[tab.key].push(it);
    });
    // Добавим отсутствующие ожидаемые ключи
    Object.entries(EXPECTED_KEYS).forEach(([tabKey, defs]) => {
      defs.forEach(def => {
        const exists = (byTab[tabKey] || []).some(i => i.key === def.key) || items.some(i => i.key === def.key);
        if (!exists) {
          const fake: SettingItem = {
            key: def.key,
            value: def.defaultValue,
            description: def.description || '',
            category: tabKey,
            data_type: def.data_type,
          };
          byTab[tabKey] = byTab[tabKey] || [];
          byTab[tabKey].push(fake);
        }
      });
    });
    // Сортировка по ключу для стабильности
    Object.keys(byTab).forEach(k => {
      byTab[k] = (byTab[k] || []).sort((a, b) => a.key.localeCompare(b.key));
    });
    return byTab;
  }, [items]);

  const saveItem = async (item: SettingItem, draft: any) => {
    try {
      setSavingKey(item.key);
      const out = normalizeOutgoingValue(item, draft);
      await fetch('/api/admin/soul/settings', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', ...buildAuthHeaders() },
        body: JSON.stringify({ key: item.key, value: out })
      });
      message.success('Сохранено');
      await loadAll();
    } catch (e: any) {
      message.error(e?.message || 'Ошибка сохранения');
    } finally {
      setSavingKey(null);
    }
  };

  const testLLM = async () => {
    try {
      setLlmTestLoading(true);
      setLlmTestResult(null);
      const res = await fetch('/api/admin/soul/llm/test?prompt=ping', { headers: buildAuthHeaders() });
      if (res.ok) {
        const data = await res.json();
        setLlmTestResult({ ok: true, provider: data?.provider || data?.current_provider });
        message.success('LLM OK');
      } else {
        const text = await res.text();
        setLlmTestResult({ ok: false, detail: text });
        message.error('LLM error');
      }
    } catch (e: any) {
      setLlmTestResult({ ok: false, detail: e?.message || 'Ошибка' });
      message.error('LLM error');
    } finally {
      setLlmTestLoading(false);
    }
  };

  if (loading) {
    return (
      <Card>
        <div style={{ textAlign: 'center', padding: 40 }}>
          <Spin size="large" />
          <div style={{ marginTop: 12 }}>Загрузка системных настроек…</div>
        </div>
      </Card>
    );
  }

  if (error) {
    return (
      <Card>
        <Alert type="error" showIcon message="Ошибка" description={error} />
      </Card>
    );
  }

  return (
    <div style={{ padding: 'var(--sp-spacing-sm)' }}>
      <Title level={2} style={{ marginTop: 0 }}>
        <SettingOutlined /> Системные настройки
      </Title>
      <Text type="secondary">Редактирование ключей в таблице soul_settings (без ребилда фронтенда)</Text>

      <Card style={{ marginTop: 'var(--sp-spacing-sm)' }}>
        <Tabs activeKey={activeTab} onChange={setActiveTab} tabPosition="top">
          {CATEGORY_TABS.map(tab => (
            <TabPane
              tab={<span>{tab.title}</span>}
              key={tab.key}
            >
              {/* Спец‑панель для LLM */}
              {tab.key === 'LLM' && (
                <div style={{ marginBottom: 'var(--sp-spacing-sm)' }}>
                  <Space>
                    <Button icon={<ReloadOutlined />} onClick={loadAll}>Перезагрузить</Button>
                    <Button type="primary" icon={<ApiOutlined />} onClick={testLLM} loading={llmTestLoading}>Проверить LLM</Button>
                    {llmTestResult && (
                      llmTestResult.ok ? (
                        <Tag color="green"><CheckCircleOutlined /> OK {llmTestResult.provider ? `• ${llmTestResult.provider}` : ''}</Tag>
                      ) : (
                        <Tag color="red"><ExclamationCircleOutlined /> Error</Tag>
                      )
                    )}
                  </Space>
                </div>
              )}
              <CategoryTable list={groups[tab.key] || []} savingKey={savingKey} onSave={saveItem} />
            </TabPane>
          ))}
        </Tabs>
      </Card>
    </div>
  );
};

export default SystemSettings;


